import subprocess
import json

# Test script in Node.js
test_code = '''
const { TokenBucket } = require('./kova.js');

// Test 1: Basic construction and initial state
const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 5 });
console.log('Test 1 - Initial tokens:', bucket.available() === 10 ? 'PASS' : 'FAIL');
console.log('Test 1 - tryTake(1):', bucket.tryTake(1) === true ? 'PASS' : 'FAIL');
console.log('Test 1 - available after take:', bucket.available() === 9 ? 'PASS' : 'FAIL');

// Test 2: Refill over time
let time = 1000;
const bucket2 = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: () => time });
console.log('Test 2 - Initial:', bucket2.available() === 10 ? 'PASS' : 'FAIL');
time += 500; // 0.5 seconds
console.log('Test 2 - After 0.5s:', bucket2.available() === 15 ? 'FAIL' : (bucket2.available() === 10 ? 'PASS (capped)' : 'FAIL'));
// Actually should be 10 (capped at capacity)
time = 1000;
const bucket3 = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: () => time });
time += 1000; // 1 second
console.log('Test 3 - After 1s:', Math.abs(bucket3.available() - 10) < 0.001 ? 'PASS' : 'FAIL - got ' + bucket3.available());

// Test 4: tryTake with insufficient tokens
const bucket4 = new TokenBucket({ capacity: 5, refillPerSecond: 1, now: () => 0 });
console.log('Test 4 - tryTake(6):', bucket4.tryTake(6) === false ? 'PASS' : 'FAIL');
console.log('Test 4 - tokens unchanged:', bucket4.available() === 5 ? 'PASS' : 'FAIL');

// Test 5: msUntil
let time5 = 0;
const bucket5 = new TokenBucket({ capacity: 10, refillPerSecond: 5, now: () => time5 });
bucket5.tryTake(8); // 2 left
console.log('Test 5 - msUntil(5):', bucket5.msUntil(5) === 600 ? 'PASS' : 'FAIL - got ' + bucket5.msUntil(5));
console.log('Test 5 - msUntil(2):', bucket5.msUntil(2) === 0 ? 'PASS' : 'FAIL - got ' + bucket5.msUntil(2));

// Test 6: msUntil Infinity cases
const bucket6 = new TokenBucket({ capacity: 10, refillPerSecond: 0, now: () => 0 });
bucket6.tryTake(5);
console.log('Test 6 - refillPerSecond=0, need more:', bucket6.msUntil(6) === Infinity ? 'PASS' : 'FAIL');
console.log('Test 6 - n > capacity:', bucket6.msUntil(11) === Infinity ? 'PASS' : 'FAIL');

// Test 7: Time going backwards
let time7 = 1000;
const bucket7 = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: () => time7 });
bucket7.tryTake(5); // 5 left
time7 = 500; // time goes back
console.log('Test 7 - Time back, tokens:', bucket7.available() === 5 ? 'PASS' : 'FAIL - got ' + bucket7.available());
time7 = 2000; // time jumps forward from max seen
console.log('Test 7 - Time forward from max:', Math.abs(bucket7.available() - 10) < 0.001 ? 'PASS' : 'FAIL - got ' + bucket7.available());

// Test 8: Fractional tokens
let time8 = 0;
const bucket8 = new TokenBucket({ capacity: 10, refillPerSecond: 3, now: () => time8 });
time8 = 100; // 0.1 seconds
console.log('Test 8 - Fractional:', Math.abs(bucket8.available() - 10) < 0.001 ? 'PASS (capped)' : 'FAIL - got ' + bucket8.available());
bucket8.tryTake(9.5); // This should fail since n must be integer

// Test 9: RangeError cases
try {
  new TokenBucket({ capacity: 0, refillPerSecond: 1 });
  console.log('Test 9 - capacity=0: FAIL');
} catch (e) {
  console.log('Test 9 - capacity=0:', e instanceof RangeError ? 'PASS' : 'FAIL');
}

try {
  new TokenBucket({ capacity: -1, refillPerSecond: 1 });
  console.log('Test 9 - capacity=-1: FAIL');
} catch (e) {
  console.log('Test 9 - capacity=-1:', e instanceof RangeError ? 'PASS' : 'FAIL');
}

try {
  new TokenBucket({ capacity: 10, refillPerSecond: -1 });
  console.log('Test 9 - refillPerSecond=-1:', e instanceof RangeError ? 'PASS' : 'FAIL');
} catch (e) {
  console.log('Test 9 - refillPerSecond=-1:', e instanceof RangeError ? 'PASS' : 'FAIL');
}

try {
  const b = new TokenBucket({ capacity: 10, refillPerSecond: 1 });
  b.tryTake(0);
  console.log('Test 9 - tryTake(0): FAIL');
} catch (e) {
  console.log('Test 9 - tryTake(0):', e instanceof RangeError ? 'PASS' : 'FAIL');
}

try {
  const b = new TokenBucket({ capacity: 10, refillPerSecond: 1 });
  b.tryTake(-1);
  console.log('Test 9 - tryTake(-1): FAIL');
} catch (e) {
  console.log('Test 9 - tryTake(-1):', e instanceof RangeError ? 'PASS' : 'FAIL');
}

try {
  const b = new TokenBucket({ capacity: 10, refillPerSecond: 1 });
  b.tryTake(1.5);
  console.log('Test 9 - tryTake(1.5): FAIL');
} catch (e) {
  console.log('Test 9 - tryTake(1.5):', e instanceof RangeError ? 'PASS' : 'FAIL');
}

try {
  const b = new TokenBucket({ capacity: 10, refillPerSecond: 1 });
  b.msUntil(0);
  console.log('Test 9 - msUntil(0): FAIL');
} catch (e) {
  console.log('Test 9 - msUntil(0):', e instanceof RangeError ? 'PASS' : 'FAIL');
}

console.log('All tests completed.');
'''

